"""Build a portable review page from verified native render captures."""
from pathlib import Path
import base64
root=Path(__file__).resolve().parents[2]/'outputs'
levels=[(1,'玄岩幼兽',0.34,0),(15,'背鳍初生',0.48,2),(25,'翠岩亚成体',0.58,2),(50,'霜蓝成体',0.76,4),(75,'熔岩完全体',0.90,7),(100,'紫晶灾厄体',1.00,9)]
def image(name):
    return 'data:image/png;base64,'+base64.b64encode((root/name).read_bytes()).decode()
cards=''.join(f'<article><header><b>LV {lv:02} · {name}</b><span>体型 ×{scale:.2f} / 晶体组 {n}</span></header><img src="{image(f"growth-L{lv}-body.png")}" alt="{name}"></article>' for lv,name,scale,n in levels)
scene=''.join(f'<article><header><b>LV {lv:02} · 游戏原生帧</b></header><img src="{image(f"growth-L{lv}.png")}" alt="游戏实帧 {lv}"></article>' for lv in [1,14,15,100])
hues=''.join(f'<article><header><b>LV50 · {label}</b><span>体型与鳍数相同，仅比较体色</span></header><img src="{image(f"growth-L50-{key}-body.png")}" alt="{label}"></article>' for key,label in [('jade','翠化'),('crimson','赤化'),('albino','白化'),('obsidian','玄化')])
html='''<!doctype html><html lang="zh-CN"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>巨兽都市 · 成长外观验收</title><style>*{box-sizing:border-box}body{margin:0;background:#080d18;color:#e5ecf8;font:15px/1.65 system-ui,"Microsoft YaHei",sans-serif}main{max-width:1240px;margin:auto;padding:48px 28px}h1{font-size:38px;line-height:1.2;margin:12px 0}h2{margin:46px 0 16px;font-size:24px}p{color:#9cacc5;max-width:880px}small,.tag{color:#72ded4;letter-spacing:2px}.grid{display:grid;grid-template-columns:1fr 1fr;gap:18px}article{overflow:hidden;border:1px solid #263248;background:#111827;border-radius:12px}header{padding:16px 18px;border-bottom:1px solid #263248;display:flex;justify-content:space-between;gap:12px}header span{color:#91a3bf;font-size:13px}img{display:block;width:100%;height:auto;image-rendering:pixelated}.note{padding:18px 22px;background:#142033;border-left:3px solid #72ded4;border-radius:6px;color:#b7c6dc}a{color:#72ded4}@media(max-width:760px){.grid{grid-template-columns:1fr}header{flex-direction:column}h1{font-size:28px}}</style><main><small>GNN / GROWTH APPEARANCE REVIEW</small><h1>从无鳍幼兽，到紫晶灾厄体</h1><p>这不是概念图。下方使用项目实际骨骼、实际皮肤和实际背鳍渲染器；第一组为相同画布、相同脚底锚点的中性姿态。游戏原生帧保留真实城市与镜头缩放。</p><div class="note">源码已接入 · 118项回归：110通过 / 0失败 / 8项macOS跳过。原始 default.png 未改，正式存档未读写，安装包尚未重新构建。</div><h2>01 / 六个成长锚点</h2><p>体型连续增长；15级首次出现2组背鳍，之后每12级增加1组。单组晶体本身自带分叉，不等同于单个尖刺。</p><div class="grid">'''+cards+'''</div><h2>02 / 门槛与城市实帧</h2><p>14级仍无背鳍，15级两组初生背鳍；高等级沿背脊延伸至尾部与颈背。以下均为游戏 canvas 输出。</p><div class="grid">'''+scene+'''</div><h2>03 / 同级体色变体</h2><p>颜色突变优先于阶段默认色。身体贴图保持相同alpha，不再把矩形色块叠到城市上；眼睛和牙爪保留原色。</p><div class="grid">'''+hues+'''</div><h2>04 / 资产与边界</h2><p>clean为修复后的无鳍身体，另外生成翠岩、霜蓝、熔岩、紫晶四组皮肤，每组覆盖12个骨骼槽。nofin/fin只用于互补重组核验；crown是已接入的独立背鳍，blade为备用资产。</p><div class="note">这是可继续扩展的初版成长美术，不是五套全新解剖结构。鳍根被遮住的身体由几何补面恢复，保留原有像素鳞甲；自动测试不能替代最终美术审阅。未改变攻击、经验、存档版本或原有体型曲线。</div></main></html>'''
(root/'growth-review.html').write_text(html,encoding='utf-8')
print('Created portable growth-review.html')
